// Valida lo que manda el panel (lib/usuarios/avisoRol.ts): { evento: 'usuario_rol', aviso_id }.
// Solo eso: destinatario y textos se leen de la MySQL en el nodo siguiente (el webhook es publico).
const body = $json.body || {};
const id = parseInt(body.aviso_id, 10);
if (body.evento !== 'usuario_rol' || !(id > 0)) return null;
return { json: { id } };

// Arma el correo de bienvenida con la fila de "Leer aviso" (usuarios_avisos_rol + users_config).
// Ningún texto ni dirección viene del webhook (es público): todo lo guardó el panel
// (lib/usuarios/avisoRol.ts). Sin fila = ya se mandó, tiene más de un día o la persona ya no tiene ese rol.
const a = $json;
if (!a || !a.id) return null;
const esCorreo = (v) => /^[^\s@<>,;()]+@[^\s@<>,;()]+\.[^\s@<>,;()]+$/.test(String(v || '').trim());
const para = String(a.email || '').trim().toLowerCase();
if (!esCorreo(para)) return null;

let grupos = [];
try { grupos = JSON.parse(a.secciones_json || '[]'); } catch (e) { grupos = []; }
if (!Array.isArray(grupos)) grupos = [];

// Marca por sede: OSC en Valencia (9), SUPRICOM en Caracas (10), Panamá (7) y sin sede.
const SEDES = { 9: 'Valencia', 10: 'Caracas', 7: 'Panamá' };
const sede = SEDES[Number(a.cids)] || '';
const M = Number(a.cids) === 9
  ? { nombre: 'OSC', logo: 'https://panel.supricom.com.ve/osclogo.jpg', ancho: 64, alto: 64, primario: '#1746C1', oscuro: '#0B1E4F', claro: '#EAF0FD', acento: '#2F80ED', razon: 'Office Solutions Center 2004, C.A.' }
  : { nombre: 'SUPRICOM', logo: 'https://panel.supricom.com.ve/supricom-reporte-logo.png', ancho: 170, alto: 52, primario: '#0E7FD1', oscuro: '#0A2540', claro: '#E8F4FC', acento: '#29ABE2', razon: Number(a.cids) === 10 ? 'SUPRICOM CCS 21, C.A.' : Number(a.cids) === 7 ? 'SUPRICOM, S.A.' : 'SUPRICOM' };
const FUENTE = "font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const url = /^https?:\/\//.test(String(a.url_panel || '')) ? String(a.url_panel) : 'https://panel.supricom.com.ve';
const rol = a.rol_nombre || a.rol;
const nombre = String(a.nombre || '').trim().split(/\s+/)[0] || '';
const cambio = !!a.rol_anterior;
const asunto = (cambio ? 'Tu rol en el Panel SUPRICOM cambió: ' : 'Tu acceso al Panel SUPRICOM: ') + rol;

const titulo = cambio ? 'Tu rol en el panel cambió' : 'Ya tienes acceso al panel';
const bajada = cambio
  ? 'Pasaste de <strong>' + esc(a.rol_anterior) + '</strong> a <strong>' + esc(rol) + '</strong>.'
  : 'Se te asignó el rol <strong>' + esc(rol) + '</strong>' + (sede ? ' en ' + esc(sede) : '') + '.';

const fila = (etiqueta, valor) => '<tr><td style="padding:10px 14px;color:#64748B;width:130px;font-size:13px;border-bottom:1px solid #EEF1F6;vertical-align:top">' + etiqueta + '</td><td style="padding:10px 14px;font-size:14px;color:#0F172A;border-bottom:1px solid #EEF1F6">' + valor + '</td></tr>';
const datos = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid #E6EAF2;border-radius:12px;background:#FAFBFD">' +
  fila('Dirección', '<a href="' + esc(url) + '" style="color:' + M.primario + ';font-weight:700">' + esc(url) + '</a>') +
  fila('Tu rol', '<strong>' + esc(rol) + '</strong>' + (sede ? ' · ' + esc(sede) : '')) +
  fila('Usuario', '<strong>' + esc(para) + '</strong>') +
  fila('Contraseña', 'La misma de <strong>Odoo</strong>') + '</table>';

const comoEntrar = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:18px 0 4px 0"><tr><td style="background:' + M.claro + ';border-radius:12px;padding:16px 18px;' + FUENTE + '">' +
  '<div style="font-size:13px;font-weight:800;color:' + M.oscuro + ';text-transform:uppercase;letter-spacing:.6px;margin-bottom:6px">Cómo iniciar sesión</div>' +
  '<div style="font-size:14px;line-height:1.55;color:#334155">Entra con tu <strong>usuario y contraseña de Odoo</strong>, los mismos con los que entras a Odoo: tu usuario es tu correo. ' +
  'El panel no tiene una contraseña aparte; si la olvidas o la quieres cambiar, se hace en Odoo.' +
  (cambio ? ' Si tenías el panel abierto, vuelve a iniciar sesión para ver tu nuevo menú.' : '') + '</div></td></tr></table>';

const secciones = grupos.map((g) =>
  '<div style="margin:18px 0 6px 0;font-size:13px;font-weight:800;color:' + M.primario + ';text-transform:uppercase;letter-spacing:.6px">' + esc(g.area) + '</div>' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' +
  (Array.isArray(g.secciones) ? g.secciones : []).map((s) =>
    '<tr><td style="padding:5px 0;font-size:14px;line-height:1.5;color:#334155"><span style="color:' + M.acento + '">●</span>&nbsp; <strong style="color:#0F172A">' + esc(s.nombre) + '</strong>: ' + esc(s.detalle) + '</td></tr>').join('') +
  '</table>').join('');

const queHace = '<div style="margin:26px 0 4px 0;font-size:18px;font-weight:800;color:' + M.oscuro + '">Qué puedes hacer con este rol</div>' +
  '<p style="margin:6px 0 0 0;font-size:15px;line-height:1.6;color:#1E293B">' + esc(a.resumen) + '</p>' +
  (secciones ? '<p style="margin:10px 0 0 0;font-size:14px;color:#64748B">Estas son las secciones de tu menú:</p>' + secciones : '');

const boton = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:26px 0 6px 0"><tr><td align="center">' +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto"><tr><td align="center" bgcolor="' + M.primario + '" style="border-radius:12px;background:linear-gradient(135deg,' + M.acento + ',' + M.primario + ')">' +
  '<a href="' + esc(url) + '" target="_blank" style="display:inline-block;padding:14px 28px;' + FUENTE + ';font-size:15px;font-weight:700;color:#FFFFFF;text-decoration:none;border-radius:12px">Entrar al panel</a></td></tr></table></td></tr></table>';

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(asunto) + '</title>' +
  '<style>@media (max-width:620px){.contenedor{width:100%!important;border-radius:0!important}.pad{padding-left:20px!important;padding-right:20px!important}.titulo{font-size:22px!important}}</style></head>' +
  '<body style="margin:0;padding:0;background:#EEF1F6">' +
  '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">' + esc(asunto) + '</div>' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#EEF1F6" style="background:#EEF1F6"><tr><td align="center" style="padding:28px 12px">' +
  '<table role="presentation" class="contenedor" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#FFFFFF;border-radius:18px;overflow:hidden;box-shadow:0 10px 30px rgba(15,30,70,.10)">' +
  '<tr><td class="pad" style="padding:20px 32px;border-bottom:1px solid #EEF1F6"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>' +
  '<td valign="middle"><img src="' + M.logo + '" width="' + M.ancho + '" height="' + M.alto + '" alt="' + M.nombre + '" style="display:block;border:0"></td>' +
  '<td valign="middle" align="right" style="' + FUENTE + '"><span style="display:inline-block;background:' + M.claro + ';color:' + M.primario + ';border-radius:999px;padding:6px 12px;font-size:12px;font-weight:700">Panel SUPRICOM' + (sede ? ' · ' + esc(sede) : '') + '</span></td></tr></table></td></tr>' +
  '<tr><td class="pad" bgcolor="' + M.primario + '" style="padding:30px 32px 28px 32px;background:linear-gradient(135deg,' + M.oscuro + ' 0%,' + M.primario + ' 60%,' + M.acento + ' 100%);' + FUENTE + '">' +
  '<div style="font-size:12px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:rgba(255,255,255,.75);margin-bottom:8px">' + (cambio ? 'Cambio de rol' : 'Bienvenida') + '</div>' +
  '<div class="titulo" style="font-size:26px;line-height:1.25;font-weight:800;color:#FFFFFF">' + titulo + '</div>' +
  '<div style="font-size:15px;line-height:1.5;color:rgba(255,255,255,.88);margin-top:8px">' + bajada + '</div></td></tr>' +
  '<tr><td class="pad" style="padding:28px 32px 10px 32px;' + FUENTE + ';font-size:15px;line-height:1.6;color:#1E293B">' +
  '<p style="margin:0 0 16px 0">Hola' + (nombre ? ' ' + esc(nombre) : '') + ',</p>' + datos + comoEntrar + boton + queHace + '</td></tr>' +
  '<tr><td class="pad" style="padding:20px 32px 26px 32px;' + FUENTE + '"><div style="border-top:1px solid #EEF1F6;padding-top:18px;font-size:12px;line-height:1.6;color:#64748B">' +
  '<strong style="color:' + M.oscuro + '">' + esc(M.razon) + '</strong>' + (sede ? ' · ' + esc(sede) : '') +
  '<br>Aviso automático del panel: sale cuando se te asigna un rol' + (a.asignado_por ? ' (lo asignó ' + esc(a.asignado_por) + ')' : '') + '. Si no esperabas este acceso, avísale a tu supervisor.</div></td></tr>' +
  '</table></td></tr></table></body></html>';

return { json: { aviso_id: Number(a.id), para, asunto: asunto.slice(0, 200), html } };
